import{z as s,x as l,o as B,c as d,q as r,j as n,D as A,d as e,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"行政数据的利用","description":"","frontmatter":{"title":"行政数据的利用","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ec-administrative-data.md","filePath":"econ/ec-administrative-data.md","lastUpdated":1791063341000}'),p={name:"econ/ec-administrative-data.md"};function D(m,E,c,f,h,u){const t=l("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="行政数据的利用" tabindex="-1">行政数据的利用 <a class="header-anchor" href="#行政数据的利用" aria-label="Permalink to &quot;行政数据的利用&quot;">​</a></h1><div class="epigraph"><p>行政记录回答的是「治理需要知道什么」；研究问的常常是另一件事——把前者当后者用之前，先读懂产生它的流程。</p><footer>—— 据 Abowd, The U.S. Census Bureau Adopts Differential Privacy, KDD 2018 整理</footer></div><p><a href="/econ/ec-data-sources">上一课</a>把来源谱系摆开、钉了口径五查，行政数据只在谱系里占一格。这一课把那一格放大：它是五类里体量最大、增长最快的一支，也是过去二十年劳动、公共与城市经济学实证重心迁移的方向——不是因为它好用，而是因为别的来源在退化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>行政数据的诱惑是规模与精度：近全样本、无回忆误差、能跨十年追踪同一个体。但它是行政过程的副产品，四个缺口随之而来。字段是管理定义：失业登记里的「失业」与劳动力调查的「失业」口径不同，把登记数当调查数用，测的是行政管理不是劳动市场。覆盖由管理边界决定：在税册上的人是申报者，不在税册上的人不是噪声，是系统性缺席。变量缺失是为省成本或为保密：你想要的协变量从未被采集。访问受保密法约束：数据不是下载的，是申请的。</p><p><span class="marginnote">口径就是一套测量规则：谁被算进来、字段按什么定义填。失业登记的『失业』要求你主动登记领取待遇，劳动力调查的『失业』要求无工作且在找工作——同一个词两种规则，两组数字不能直接对表。</span></p><h3 id="利用四步" tabindex="-1">利用四步 <a class="header-anchor" href="#利用四步" aria-label="Permalink to &quot;利用四步&quot;">​</a></h3><p><span class="marginnote">2020 年美国人口普查为防重识别注入差分隐私噪声：隐私损失预算在州、县、街区块之间怎么分配，直接改变小区域数据的可用形状——保密技术从此是口径的一部分，要跟数据手册一起读，而不是事后当局限。</span></p><p>第一步读懂流程：谁、在什么激励下、什么时点录入这条记录，漏登与错登集中在流程哪一段。第二步口径映射：把行政分类显式翻译成研究构念，翻译不了的字段宁可不用。第三步进入协议：统计机构的安全环境、远程执行、输出审查——「代码进、人不出」是常态，研究工作流要为此设计，环境课接着讲。第四步保密技术：去识别、\\(k\\)-匿名、差分隐私；它们不只是约束，也改变数据本身的形状。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',10)),(B(),n(i,null,{default:A(()=>[o(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROC%5B%22%E8%A1%8C%E6%94%BF%E6%B5%81%E7%A8%8B%3A%20%E8%B0%81%E4%B8%BA%E4%BD%95%E6%97%B6%E7%82%B9%E5%BD%95%E5%85%A5%22%5D%20--%3E%20MAP%5B%22%E5%8F%A3%E5%BE%84%E6%98%A0%E5%B0%84%3A%20%E7%AE%A1%E7%90%86%E5%AE%9A%E4%B9%89%E5%88%B0%E7%A0%94%E7%A9%B6%E6%9E%84%E5%BF%B5%22%5D%0A%20%20MAP%20--%3E%20ACC%5B%22%E8%BF%9B%E5%85%A5%E5%8D%8F%E8%AE%AE%3A%20%E5%AE%89%E5%85%A8%E7%8E%AF%E5%A2%83%2F%E8%BF%9C%E7%A8%8B%E6%89%A7%E8%A1%8C%2F%E8%BE%93%E5%87%BA%E5%AE%A1%E6%9F%A5%22%5D%0A%20%20ACC%20--%3E%20DP%5B%22%E4%BF%9D%E5%AF%86%E6%8A%80%E6%9C%AF%3A%20%E5%8E%BB%E8%AF%86%E5%88%AB%2F%E5%B7%AE%E5%88%86%E9%9A%90%E7%A7%81%22%5D%0A%20%20DP%20--%3E%20WHO%5B%22%E8%B0%81%E4%B8%8D%E5%9C%A8%E8%BF%99%E5%BC%A0%E8%A1%A8%E9%87%8C%22%5D%0A%20%20WHO%20--%3E%20EST%5B%22%E8%AF%86%E5%88%AB%3A%20%E9%9D%A2%E6%9D%BF%E4%B8%8E%E6%96%AD%E9%9D%A2%E7%9A%84%E5%8F%98%E5%BC%82%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[e("两个范本。其一，Chetty–Friedman–Rockoff 2014 用学区行政记录把数十年前的学生与教师连到成年后的税务记录，把教师质量对长期收入的效应做成可估量——全样本与长纵深使这种跟踪在调查里不可能。其二，Autor–Dorn–Hanson 2013 用海关贸易数据与产业面板度量本地劳动力市场的进口竞争暴露（"),a("a",{href:"/econ/china-shock"},"中国冲击"),e("），行政数据的高频与细分把处理的断面做细，"),a("a",{href:"/econ/difference-in-differences"},"双重差分"),e("才有得吃。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"行政数据的识别优势拆成两条：覆盖把小群体变成可估计的样本——小城镇、细分子行业、少数族裔细分组；纵深把跨代、跨企业的长期结果连成面板。但「全」是行政边界内的全：与管理系统的接触本身可能相关于结果，不报税、不登记、不入学的人，恰恰是许多政策问题里最重要的人。所以用行政数据做识别，识别假设的清单第一行写的是「谁不在这张表里、为何不在」，然后才是处理效应；进入行政系统的选择不是稳健性附录，是识别假设本身。",-1)),E[6]||(E[6]=a("p",null,"「接近全样本为什么仍可能有偏」——进入选择的几何：",-1)),(B(),n(i,null,{default:A(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E8%A1%8C%E6%94%BF%E7%B3%BB%E7%BB%9F%22%5D%20--%3E%20IN%5B%22%E8%A1%A8%E5%86%85%3A%20%E4%B8%8E%E7%B3%BB%E7%BB%9F%E6%9C%89%E6%8E%A5%E8%A7%A6%E8%80%85%22%5D%0A%20%20SYS%20--%3E%20OUT%5B%22%E8%A1%A8%E5%A4%96%3A%20%E4%B8%8D%E6%8A%A5%E7%A8%8E%E4%B8%8D%E7%99%BB%E8%AE%B0%E8%80%85%22%5D%0A%20%20OUT%20--%3E%20SEL%5B%22%E7%BC%BA%E5%B8%AD%E4%B8%8E%E7%BB%93%E6%9E%9C%E7%9B%B8%E5%85%B3%22%5D%0A%20%20SEL%20--%3E%20BIAS%5B%22%E8%A1%A8%E5%86%85%E7%9B%B8%E5%85%B3%20%E4%B8%8D%E7%AD%89%E4%BA%8E%20%E6%80%BB%E4%BD%93%E5%85%B3%E7%B3%BB%22%5D%0A%20%20IN%20--%3E%20EST%5B%22%E8%A1%A8%E5%86%85%E4%BC%B0%E8%AE%A1%E7%9A%84%E5%A4%84%E7%90%86%E6%95%88%E5%BA%94%22%5D%0A%20%20BIAS%20--%3E%20CHECK%5B%22%E7%AC%AC%E4%B8%80%E8%A1%8C%E8%AF%86%E5%88%AB%E5%81%87%E8%AE%BE%3A%20%E8%B0%81%E4%B8%8D%E5%9C%A8%20%E4%B8%BA%E4%BD%95%E4%B8%8D%E5%9C%A8%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<p><span class="marginnote">差分隐私可类比在集体合影上撒细沙：单个人看不清（隐私受保护），想数清某个小方块里站了几个人也变难（小区域统计失真）。沙子撒多粗、往哪里撒，由隐私预算决定——所以它是口径的一部分。</span></p><p>不这么做会错在哪：拿登记口径的失业当调查失业做时间序列；把覆盖变化（扩围、并轨）误读成行为变化；不写清进入机制，把「表内相关」读成总体关系。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>行政数据不是免费午餐：申请周期长、变量僵化、敏感结论要过输出审查，而且「为研究复制一份历史库」常受保密约束——这让复现工程的权重更高，是环境课的主题。它与调查是互补不是替代：行政缺动机与态度变量，调查缺样本量与代表性锚点，两者怎么组合是下一课。爬取型「准行政」数据另算：它的生成机制更接近网络与文本，回到<a href="/econ/ec-data-sources">第一课</a>的谱系与<a href="/econ/pm-text-as-data">文本测量</a>的验证纪律。</p><p><span class="marginnote">常见误区：说『这是接近全体人口的数据，所以没有样本偏差』。研究失业救济时，从未申报的人可能正是最脱离市场的一群——他们不在表里，任何只看表内的结论都会系统性漏掉最需要政策的人。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>行政数据是治理过程的沉淀：字段是管理定义，覆盖是管理边界，访问是法律协议。</li><li>利用四步：读流程、映射口径、进协议、读保密技术；「谁不在这张表里」是识别假设的一部分。</li><li>覆盖与纵深是小群体与长期结果的识别来源，代价是进入成本与变量僵化。</li><li>差分隐私等保密技术改变数据形状，属于口径而非外部约束。</li><li>出处：Abowd, <em>KDD</em> 2018；Chetty, Friedman and Rockoff, <em>AER</em> 2014；Autor, Dorn and Hanson, <em>AER</em> 2013。</li></ul>',7))])}const _=s(p,[["render",D]]);export{F as __pageData,_ as default};
